#!/bin/bash
# CIFAR-10, ViT-micro d=32, all 7 arms in one job. Writes to benchmarks/outputs/vit_micro_cifar/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/train_vit_micro_cifar_all.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=vit_micro_cifar_all
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=00:35:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: 7 x T_diag = 7 x 56 s = ~6.5 min of training.
# Dataset: cifar10 must be staged under $SLURM_SUBMIT_DIR/dataset (compute nodes have no
# internet; --no-allow-download turns a missing dataset into a clear error, not a timeout).

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"

# All 7 arms of one model, in ONE job (plan_exp_step1.md D3's runner does the whole WCT
# protocol in-process): the reference arm runs 30 epochs unbudgeted, its measured elapsed
# time becomes every other arm's budget, and one combined report is written at the end. No
# WCT_BUDGET to pass, no dispatcher, no --dependency.
#
# The per-arm alternative is benchmarks/slurm/train_vit_micro_cifar_<arm>.sh, one job each; use it if you
# need the arms to run concurrently, or if you want a crash in one arm not to cost the others.
python -m benchmarks.vit_micro_cifar.bench \
  --arms diag kfac ekfac tkfac tekfac adam adamw \
  --epochs 30 \
  --budget-mode wct \
  --reference-arm diag \
  --max-epoch-factor 3 \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$SLURM_SUBMIT_DIR/dataset" \
  --checkpoints 0,0.01,0.1,0.5,1 \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/vit_micro_cifar"
